   "codice": "extends RefCounted

func run() -> float:
	var min_deg: float = -80.0
	var max_deg: float = 30.0
	var current: float = 45.0
	return clampf(current, min_deg, max_deg)
",
   "domanda": "Quanto vale il numero restituito da `run()`?",
   "spiegazione": "`current` (45.0) supera il limite massimo (`max_deg` = 30.0), quindi `clampf` lo blocca esattamente a 30.0."
  },
