   "codice": "extends RefCounted

func run() -> float:
	var base_length: float = 5.0
	var min_length: float = 1.0
	var zoom_step: float = 6.0
	return clampf(base_length - zoom_step, min_length, 10.0)
",
   "domanda": "Quanto vale il numero restituito da `run()`?",
   "spiegazione": "`base_length - zoom_step` fa `-1.0`. Applicando `clampf` con limite minimo `1.0`, il valore viene bloccato al minimo consentito, cioè `1.0`."
