  {
   "codice": "extends RefCounted

func run() -> float:
	var rel_x: float = 150.0
	var sensitivity: float = 0.003
	var current_y: float = 1.5
	return current_y - (rel_x * sensitivity)
",
   "domanda": "Quanto vale il numero restituito da `run()`?",
   "spiegazione": "150.0 moltiplicato per 0.003 dà 0.45. Sottraendo questo risultato da 1.5 si ottiene 1.05."
